NOFOLLOW = {f"tests/test_spawner_{module}.py::{name}"
            for module, names in _NOFOLLOW.items() for name in names.split()}


def skip_reason(nodeid, platform, fixtures):
    if platform != "win32":
        return None
    if "fake_ownership" in fixtures:
        return "Linux /proc/<pid>/stat birth identity required by fake_ownership"
    module, _, name = nodeid.partition("::")
    if (module == "tests/test_spawner_utility_props_sweep.py" or
        module == "tests/test_spawner_utility_props.py" and name.split("[", 1)[0] not in (
            "test_context_window_invalid_values_raise",
            "test_context_window_missing_uses_default", "test_price_cliff_invalid_nan_raises")):
        return "POSIX SIGALRM/setitimer required to bound resolver calls"
    if nodeid.split("[", 1)[0] in NOFOLLOW:
        return "POSIX O_NOFOLLOW unavailable; production config reader refuses by design"
    return None
